static map<GLFWwindow*, NativeRasteriser*> window_rasterisers;

void NativeRasteriser::keyFunction(GLFWwindow* window, int key, int scancode, int action, int mods)
{
    window_rasterisers[window]->pending_keys.push(KeyEvent{ key, action != GLFW_RELEASE, static_cast<KeyEvent::Modifier>(mods) });
}

void NativeRasteriser::charFunction(GLFWwindow* window, unsigned int chr)
{
    window_rasterisers[window]->pending_chars.push(chr);
}

NativeRasteriser::NativeRasteriser()
{
    glfwInit();
    glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 3);
    glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);
    window = glfwCreateWindow(1280, 960, "STRN", nullptr, nullptr);
    glfwMakeContextCurrent(window);
    window_rasterisers[window] = this;
    glfwSetKeyCallback(window, keyFunction);
    glfwSetCharCallback(window, charFunction);
    // TODO: use char func to capture typing chars
    if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress))
        throw runtime_error("failed to initialize GLAD");
    setSize({ 132, 48 });

    glGenBuffers(1, &vertex_buffer);
    glGenBuffers(1, &index_buffer);

    unsigned int vertex_shader = glCreateShader(GL_VERTEX_SHADER);
    glShaderSource(vertex_shader, 1, &vertex_shader_source, nullptr);
    glCompileShader(vertex_shader);
    int status;
    glGetShaderiv(vertex_shader, GL_COMPILE_STATUS, &status);
    if (!status)
    {
        string error; error.resize(512);
        glGetShaderInfoLog(vertex_shader, static_cast<int>(error.size()), nullptr, const_cast<char*>(error.data()));
        throw runtime_error("vertex shader error: " + error);
    }

    unsigned int fragment_shader = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(fragment_shader, 1, &fragment_shader_source, nullptr);
    glCompileShader(fragment_shader);
    glGetShaderiv(fragment_shader, GL_COMPILE_STATUS, &status);
    if (!status)
    {
        string error; error.resize(512);
        glGetShaderInfoLog(fragment_shader, static_cast<int>(error.size()), nullptr, const_cast<char*>(error.data()));
        throw runtime_error("fragment shader error: " + error);
    }

    shader_program = glCreateProgram();
    glAttachShader(shader_program, vertex_shader);
    glAttachShader(shader_program, fragment_shader);
    glLinkProgram(shader_program);
    glGetProgramiv(shader_program, GL_LINK_STATUS, &status);
    if (!status)
    {
        string error; error.resize(512);
        glGetProgramInfoLog(shader_program, static_cast<int>(error.size()), nullptr, const_cast<char*>(error.data()));
        throw runtime_error("shader program error: " + error);
    }
    transform_var = glGetUniformLocation(shader_program, "world_to_clip");
    distortion_var = glGetUniformLocation(shader_program, "distortion");
    glDeleteShader(vertex_shader);
    glDeleteShader(fragment_shader);

    glGenVertexArrays(1, &vertex_array_object);
    glBindVertexArray(vertex_array_object);
    glBindBuffer(GL_ARRAY_BUFFER, vertex_buffer);
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, index_buffer);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, sizeof(Vertex), static_cast<void*>(nullptr));
    glEnableVertexAttribArray(0);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, sizeof(Vertex), reinterpret_cast<void*>((offsetof(Vertex, vertex_colour_a))));
    glEnableVertexAttribArray(1);
    glVertexAttribPointer(2, 3, GL_FLOAT, GL_FALSE, sizeof(Vertex), reinterpret_cast<void*>((offsetof(Vertex, vertex_colour_b))));
    glEnableVertexAttribArray(2);
    glVertexAttribPointer(3, 2, GL_FLOAT, GL_FALSE, sizeof(Vertex), reinterpret_cast<void*>((offsetof(Vertex, vertex_uv))));
    glEnableVertexAttribArray(3);

    glClearColor(1.0f, 0.0f, 1.0f, 1.0f);

    glDisable(GL_DEPTH_TEST);
    glDisable(GL_CULL_FACE);

    glGenTextures(1, &font_texture);
    glBindTexture(GL_TEXTURE_2D, font_texture);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RED, 320, 144, 0, GL_RED, GL_UNSIGNED_BYTE, ibm_model30r0_font);
}

void NativeRasteriser::setWindowSize(const int w, const int h) const
{ glfwSetWindowSize(window, w * char_width, h * char_height); }

void NativeRasteriser::setScaleFactor(const size_t value)
{ scale_factor = value; }

bool NativeRasteriser::update()
{
    if (glfwWindowShouldClose(window))
        return true;
    glfwPollEvents();
    glfwGetFramebufferSize(window, &width, &height);
    const Vec2 size = calculateSize();
    pitch = size.x;
    setSize(size);
    return false;
}

KeyEvent NativeRasteriser::getKeyEvent()
{
    if (pending_keys.empty())
        return { };
    else
    {
        auto key = pending_keys.front();
        pending_keys.pop();
        return key;
    }
}

unsigned int NativeRasteriser::getCharEvent()
{
    if (pending_chars.empty())
        return 0;
    else
    {
        auto key = pending_chars.front();
        pending_chars.pop();
        return key;
    }
}

static const float* getFloatColourFromBits(const Colour c)
{
    static const float colours[16][3] =
    {
        { 0.00f, 0.00f, 0.00f },
        { 0.75f, 0.00f, 0.00f },
        { 0.00f, 0.75f, 0.00f },
        { 0.75f, 0.50f, 0.00f },
        { 0.00f, 0.00f, 0.75f },
        { 0.75f, 0.00f, 0.75f },
        { 0.00f, 0.75f, 0.75f },
        { 0.75f, 0.75f, 0.75f },
        { 0.30f, 0.30f, 0.30f },
        { 0.90f, 0.30f, 0.30f },
        { 0.30f, 0.90f, 0.30f },
        { 0.95f, 0.95f, 0.30f },
        { 0.30f, 0.30f, 0.90f },
        { 0.95f, 0.30f, 0.95f },
        { 0.30f, 0.95f, 0.95f },
        { 1.00f, 1.00f, 1.00f }
    };
    return colours[c];
}

void NativeRasteriser::present()
{
    vector<Vertex> vertices;
    vector<unsigned int> indices;
    float position[2] = { 0.0f, 0.0f };
    constexpr float uv_size[2] = {
        8.0f / 320.0f,
        -16.0f / 144.0f,
    };
    size_t x = 0;
    for (const auto it : getContext())
    {
        const float uv[2] = {
            (static_cast<float>(it.value % 32) / 32.0f),
            1.0f - (static_cast<float>(it.value / 32) / 8.0f) + (2.0f / 144.0f),
        };
        const float* fg_colour = getFloatColourFromBits(foreground(it.colour_bits));
        const float* bg_colour = getFloatColourFromBits(static_cast<Colour>(background(it.colour_bits) >> 4));

        const unsigned int offset = static_cast<unsigned int>(vertices.size());
        vertices.push_back({ // bottom left
            { position[0], position[1] + char_height, 0 },
            { fg_colour[0], fg_colour[1], fg_colour[2] },
            { bg_colour[0], bg_colour[1], bg_colour[2] },
            { uv[0], uv[1] + uv_size[1] }
        });
        vertices.push_back({ // bottom right
            { position[0] + char_width, position[1] + char_height, 0 },
            { fg_colour[0], fg_colour[1], fg_colour[2] },
            { bg_colour[0], bg_colour[1], bg_colour[2] },
            { uv[0] + uv_size[0], uv[1] + uv_size[1] }
        });
        vertices.push_back({ // top left
            { position[0], position[1], 0 },
            { fg_colour[0], fg_colour[1], fg_colour[2] },
            { bg_colour[0], bg_colour[1], bg_colour[2] },
            { uv[0], uv[1] }
        });
        vertices.push_back({ // top right
            { position[0] + char_width, position[1], 0 },
            { fg_colour[0], fg_colour[1], fg_colour[2] },
            { bg_colour[0], bg_colour[1], bg_colour[2] },
            { uv[0] + uv_size[0], uv[1] }
        });

        indices.push_back(offset + 1);
        indices.push_back(offset + 3);
        indices.push_back(offset + 0);
        indices.push_back(offset + 3);
        indices.push_back(offset + 2);
        indices.push_back(offset + 0);

        ++x;
        if (x >= pitch)
        {
            position[0] = 0.0f;
            position[1] += char_height;
            x = 0;
        }
        else
            position[0] += char_width;
    }
    glBindBuffer(GL_ARRAY_BUFFER, vertex_buffer);
    glBufferData(GL_ARRAY_BUFFER, static_cast<GLsizeiptr>(sizeof(Vertex) * vertices.size()), vertices.data(), GL_STATIC_DRAW);
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, index_buffer);
    glBufferData(GL_ELEMENT_ARRAY_BUFFER, static_cast<GLsizeiptr>(sizeof(unsigned int) * indices.size()), indices.data(), GL_STATIC_DRAW);
    mesh_index_count = static_cast<int>(indices.size());

    glViewport(0, 0, width, height);
    const float* bg_colour = getFloatColourFromBits(static_cast<Colour>(background(clear) >> 4));
    glClearColor(bg_colour[0], bg_colour[1], bg_colour[2], 1.0f);
    glClear(GL_COLOR_BUFFER_BIT);
    const float transform[16] =
    {
        2.0f / static_cast<float>(width) * static_cast<float>(scale_factor), 0, 0, 0,
        0, -2.0f / static_cast<float>(height) * static_cast<float>(scale_factor), 0, 0,
        0, 0, 1, 0,
        -1, 1, 0, 1
    };
    glUseProgram(shader_program);
    glBindTexture(GL_TEXTURE_2D, font_texture);
    glBindVertexArray(vertex_array_object);
    glUniformMatrix4fv(transform_var, 1, GL_FALSE, transform);
    glUniform1f(distortion_var, distortion);
    glPolygonMode(GL_FRONT_AND_BACK, GL_FILL);
    glDrawElements(GL_TRIANGLES, mesh_index_count, GL_UNSIGNED_INT, nullptr);

    glfwSwapBuffers(window);
}

Vec2 NativeRasteriser::calculateSize() const
{
    float wide = static_cast<float>(width) / (static_cast<float>(char_width) * static_cast<float>(scale_factor));
    if (wide <= 0.0f)
        wide = 1.0f;
    float high = static_cast<float>(height) / (static_cast<float>(char_height) * static_cast<float>(scale_factor));
    if (high <= 0.0f)
        high = 1.0f;
    return Vec2{ static_cast<int>(floorf(wide)), static_cast<int>(floorf(high)) };    
}
